      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O texto cita, em nível muito geral, sistemas de segurança, detecção de gases, proteção e combate a incêndio, além de comunicação e salvatagem como componentes de projetos de instalações offshore.",
          "trechos": [
            "Ef43aeda24ead7fa1:0:692"
          ],
          "condicoes": [
            "Descrição ampla de áreas de projeto e engenharia"
          ],
          "limites": [
            "Não trata especificamente de coletes, roupas de imersão, resgate de homem ao mar ou interação com embarcações de apoio",
            "Não apresenta mecanismos, critérios de seleção, dosagem, controle ou compatibilidade aplicáveis ao recorte"
          ]
        }
      ]
    }
